using System;using UnityEditor;using UnityEngine;using UnityEngine.UI;using ProjectSS.Expedition;
public static class HeroCardPrefabQA {
 public static string Execute(){var asset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Prefabs/UI/HeroCard.prefab");var root=PrefabUtility.LoadPrefabContents("Assets/Resources/Prefabs/PlayPage.prefab");try{var page=root.GetComponent<PlayPage>();if(asset.GetComponent<HeroCollectionCell>().page!=null)throw new Exception("External page reference");for(int i=0;i<8;i++){var card=page.heroGrid.transform.Find("HeroCard"+i);if(PrefabUtility.GetCorrespondingObjectFromSource(card.gameObject)!=asset)throw new Exception("Not a shared instance: "+i);var cell=card.GetComponent<HeroCollectionCell>();if(cell.page!=page||cell.hero!=(i<3?i:-1))throw new Exception("Binding: "+i);if(i<3&&(cell.portrait.sprite.name!="Hero_"+i||page.formationPanel.collectionCells[i]!=cell))throw new Exception("Portrait binding: "+i);if(card.GetComponent<Button>().onClick.GetPersistentTarget(0)!=cell)throw new Exception("Click target: "+i);if(card.Find("Unknown").gameObject.activeSelf!=(i>=3))throw new Exception("Placeholder: "+i);}return "PASS: eight nested HeroCard instances, distinct portraits, internal click targets and page bindings survive prefab reload.";}finally{PrefabUtility.UnloadPrefabContents(root);}}
}
